// Test view + scope syntax variants to find what the parser accepts
const base = `workspace "T" "d" {
    model {
        p = person "P" "d"
        s = softwareSystem "S" "d" {
            c = container "C" "d"
            p -> c "uses"
        }
    }
}`;

const variants = {
  "scope_line": base.replace("    model {", '    scope "Landscape"\n    model {'),
  "view_2str": base.replace("    }\n}", '    }\n    views {\n        container s "key" "Name" {\n            include *\n            autoLayout\n        }\n    }\n}'),
  "view_3str": base.replace("    }\n}", '    }\n    views {\n        container s "key" "Name" "Desc" {\n            include *\n            autoLayout\n        }\n    }\n}'),
};

const out = {};
for (const [name, dsl] of Object.entries(variants)) {
  const v = await tools.structurizr.validate({ dsl });
  out[name] = v;
}
return JSON.stringify(out, null, 2);

